export type Role = { grants: string[]; parent?: string };
export type Directory = Record<string, Role>;
export type User = { id: string; roles: string[]; denied: string[] };
export type Report = { id: string; title: string; body: string };
export type Download = { status: number; body: string };
# Report downloads

The host injects a workspace directory snapshot and a report store. Directory entries carry grants and an optional parent link. Access decisions and download responses are synchronous so the same service can run in workers and web handlers.

